mapper.select:
select st.*,stv.id as valueId,stv.template_type_name as templateTypeNameValue from system_template st left join
system_template_value stv on st.template_type= stv.template_type and stv.site_uid=#{siteUid}



        AND st.business_type =#{businessType}


        AND st.template_type like   concat('%',#{templateType},'%')



order by st.create_time desc
LIMIT #{page} OFFSET #{offset}

select count(*) from system_template st left join system_template_value stv on st.template_type=
stv.template_type and stv.site_uid=#{siteUid}


        AND st.business_type =#{businessType}


        AND st.template_type like   concat('%',#{templateType},'%')
